package com.pipican.boss;
import java.util.List;
import net.minecraft.core.particles.ParticleTypes;import net.minecraft.network.syncher.*;import net.minecraft.server.level.ServerLevel;import net.minecraft.sounds.SoundEvents;import net.minecraft.world.BossEvent;import net.minecraft.world.damagesource.DamageSource;import net.minecraft.world.entity.*;import net.minecraft.world.entity.ai.attributes.Attributes;import net.minecraft.world.level.Level;import net.minecraft.world.level.storage.ValueInput;import net.minecraft.world.level.storage.ValueOutput;
/** Runic titan with persisted circuit state and a single phase transition. */
public final class DurmagonEntity extends RegionalBossEntity{
 private static final EntityDataAccessor<Integer>ACTION=SynchedEntityData.defineId(DurmagonEntity.class,EntityDataSerializers.INT);private static final List<String>PATTERN=List.of("basic",DurmagonCombat.CIRCUIT,DurmagonCombat.REBOUNDS,DurmagonCombat.STAMP);private final DurmagonCombat combat=new DurmagonCombat(this);private int sequence,transitionTicks,summoningTicks;
 public DurmagonEntity(EntityType<? extends RegionalBossEntity>t,Level l){super(t,l,"durmagon_runic_titan",BossEvent.BossBarColor.PURPLE,240);}public static net.minecraft.world.entity.ai.attributes.AttributeSupplier.Builder attributes(){var d=BossDesigns.require("durmagon_runic_titan");return net.minecraft.world.entity.monster.Monster.createMonsterAttributes().add(Attributes.MAX_HEALTH,d.health()).add(Attributes.ATTACK_DAMAGE,d.damage()).add(Attributes.ARMOR,22).add(Attributes.MOVEMENT_SPEED,.17).add(Attributes.FOLLOW_RANGE,48).add(Attributes.KNOCKBACK_RESISTANCE,.95);}
 @Override protected void defineSynchedData(SynchedEntityData.Builder b){super.defineSynchedData(b);b.define(ACTION,0);}public int durmagonAction(){return entityData.get(ACTION);}@Override public boolean beginAbility(BossCombatState.Ability a,LivingEntity t){return false;}@Override void activateEncounter(){super.activateEncounter();summoningTicks=80;}
 @Override protected void tickBossCombat(ServerLevel l){if(summoningTicks>0){summoningTicks--;getNavigation().stop();if(summoningTicks%5==0)l.sendParticles(ParticleTypes.END_ROD,getX(),getY()+.8,getZ(),18,.7,.6,.7,.01);entityData.set(ACTION,summoningTicks>0?6:0);return;}if(combat.updatePhase(getHealth(),getMaxHealth())){transitionTicks=100;playSound(SoundEvents.LIGHTNING_BOLT_THUNDER,1.2f,.65f);}if(transitionTicks>0){getNavigation().stop();if(transitionTicks%5==0)l.sendParticles(ParticleTypes.ELECTRIC_SPARK,getX(),getY()+1,getZ(),20,.8,.8,.8,.03);transitionTicks--;entityData.set(ACTION,5);syncCombat(2,BossCombatState.Ability.PHASE_CHANGE,transitionTicks);return;}var target=getTarget();if(target!=null&&(!target.isAlive()||!insideArena(target.position()))){setTarget(null);target=null;}if(target!=null&&combat.clock().active().isEmpty()&&combat.clock().cooldown()==0&&hasLineOfSight(target)){String id=PATTERN.get(Math.floorMod(sequence,PATTERN.size()));if(id.equals("basic")&&distanceToSqr(target)>30)id=DurmagonCombat.REBOUNDS;if(combat.begin(id,target))sequence=(sequence+1)%PATTERN.size();}if(combat.clock().active().isEmpty()){if(target!=null)getNavigation().moveTo(target,.65);}else getNavigation().stop();combat.tick(l);String a=combat.clock().active();entityData.set(ACTION,a.isEmpty()?0:a.equals("basic")?1:a.equals(DurmagonCombat.CIRCUIT)?2:a.equals(DurmagonCombat.REBOUNDS)?3:4);syncCombat(combat.clock().phase(),BossCombatState.Ability.NONE,combat.clock().remaining());}
 @Override protected void addAdditionalSaveData(ValueOutput o){super.addAdditionalSaveData(o);combat.save(o);o.putInt("DurmagonSequence",sequence);o.putInt("DurmagonTransition",transitionTicks);o.putInt("DurmagonSummoning",summoningTicks);}@Override protected void readAdditionalSaveData(ValueInput i){super.readAdditionalSaveData(i);combat.load(i);sequence=Math.floorMod(i.getIntOr("DurmagonSequence",0),PATTERN.size());transitionTicks=Math.clamp(i.getIntOr("DurmagonTransition",0),0,100);summoningTicks=Math.clamp(i.getIntOr("DurmagonSummoning",0),0,80);String a=combat.clock().active();entityData.set(ACTION,summoningTicks>0?6:transitionTicks>0?5:a.isEmpty()?0:a.equals("basic")?1:a.equals(DurmagonCombat.CIRCUIT)?2:a.equals(DurmagonCombat.REBOUNDS)?3:4);syncCombat(combat.clock().phase(),summoningTicks>0?BossCombatState.Ability.SUMMONING:transitionTicks>0?BossCombatState.Ability.PHASE_CHANGE:BossCombatState.Ability.NONE,summoningTicks>0?summoningTicks:transitionTicks>0?transitionTicks:combat.clock().remaining());}
 @Override protected void dropCustomDeathLoot(ServerLevel l,DamageSource s,boolean killed){spawnAtLocation(l,new net.minecraft.world.item.ItemStack(com.pipican.worldgen.RegionalOreRegistries.MATERIALS.get("runic_iron").get(),8));spawnAtLocation(l,new net.minecraft.world.item.ItemStack(BossContent.DURMAGON_TROPHY.get()));}
}
